I18N = ROOT / 'app/src/main/java/com/yakalimi/app/I18n.java'

# Calendar state: preserve the viewed month/date while the Activity is alive.
s = MAIN.read_text(encoding='utf-8')
field_anchor = '''    private static final long BACK_EXIT_WINDOW_MS = 2000L;\n    private Medicine draft;'''
field_repl = '''    private static final long BACK_EXIT_WINDOW_MS = 2000L;\n    private java.time.YearMonth historyMonth = java.time.YearMonth.now();\n    private LocalDate historySelectedDate = LocalDate.now();\n    private Medicine draft;'''
if field_anchor not in s:
    raise SystemExit('calendar history field anchor missing')
s = s.replace(field_anchor, field_repl, 1)

old = '''    private void showHistory() {\n        screen="history";resetContent(I18n.t(this,"history"),"history");List<Medicine> meds=MedicationStore.getMedicines(this);LocalDate today=LocalDate.now();\n        if(meds.isEmpty()){content.addView(text(I18n.t(this,"no_meds_period"),18,MUTED,false));return;}\n        for(int d=0;d<14;d++){\n            LocalDate date=today.minusDays(d);TextView dh=text(TimeUtil.date(this,date),20,d==0?TEXT:MUTED,d==0);dh.setPadding(dp(4),dp(8),0,dp(8));content.addView(dh);\n            boolean any=false;\n            for(Medicine m:meds){if(!MedicationStore.isDayEnabled(m,date))continue;for(String slot:m.times){any=true;boolean taken=MedicationStore.isTaken(this,m.id,date,slot);LinearLayout row=card();row.setOrientation(LinearLayout.HORIZONTAL);row.setGravity(Gravity.CENTER_VERTICAL);\n                TextView icon=text(taken?"✓":"–",22,taken?Color.WHITE:MUTED,true);icon.setGravity(Gravity.CENTER);icon.setBackground(round(taken?BLUE:Color.rgb(242,244,247),26,0,0));row.addView(icon,new LinearLayout.LayoutParams(dp(52),dp(52)));\n                LinearLayout tx=new LinearLayout(this);tx.setOrientation(LinearLayout.VERTICAL);tx.setPadding(dp(12),0,0,0);tx.addView(text(m.name+" · "+TimeUtil.time(this,slot),18,TEXT,true));tx.addView(text(taken?I18n.t(this,"dose_taken_prefix",TimeUtil.time(this,MedicationStore.takenTime(this,m.id,date,slot))):I18n.t(this,"no_record"),15,taken?MUTED:WARNING,false));row.addView(tx,new LinearLayout.LayoutParams(0,ViewGroup.LayoutParams.WRAP_CONTENT,1));\n                if(taken)row.setOnClickListener(v->confirmUndo(m.id,date,slot));content.addView(row,matchWrap(0,dp(7)));\n            }}\n            if(!any){TextView none=text(I18n.t(this,"no_scheduled"),15,MUTED,false);none.setPadding(dp(8),0,0,dp(8));content.addView(none);}\n        }\n    }'''

new = '''    private void showHistory() {\n        screen="history";\n        resetContent(I18n.t(this,"history"),"history");\n        List<Medicine> meds=MedicationStore.getMedicines(this);\n        if(meds.isEmpty()){content.addView(text(I18n.t(this,"no_meds_period"),18,MUTED,false));return;}\n\n        if(historyMonth==null) historyMonth=java.time.YearMonth.now();\n        if(historySelectedDate==null) historySelectedDate=LocalDate.now();\n\n        LinearLayout calendar=card();\n        calendar.setPadding(dp(12),dp(14),dp(12),dp(14));\n\n        LinearLayout monthRow=new LinearLayout(this);\n        monthRow.setOrientation(LinearLayout.HORIZONTAL);\n        monthRow.setGravity(Gravity.CENTER_VERTICAL);\n        Button prev=smallButton("‹");\n        prev.setContentDescription(I18n.t(this,"previous_month"));\n        prev.setOnClickListener(v->moveHistoryMonth(-1));\n        monthRow.addView(prev,new LinearLayout.LayoutParams(dp(54),dp(46)));\n\n        java.util.Locale calendarLocale=java.util.Locale.forLanguageTag(I18n.language(this).replace('_','-'));\n        String monthName=historyMonth.getMonth().getDisplayName(java.time.format.TextStyle.FULL,calendarLocale);\n        TextView monthTitle=text(historyMonth.getYear()+"  "+monthName,21,TEXT,true);\n        monthTitle.setGravity(Gravity.CENTER);\n        monthRow.addView(monthTitle,new LinearLayout.LayoutParams(0,ViewGroup.LayoutParams.WRAP_CONTENT,1));\n\n        Button next=smallButton("›");\n        next.setContentDescription(I18n.t(this,"next_month"));\n        next.setOnClickListener(v->moveHistoryMonth(1));\n        monthRow.addView(next,new LinearLayout.LayoutParams(dp(54),dp(46)));\n        calendar.addView(monthRow);\n\n        TextView hint=text(I18n.t(this,"calendar_hint"),14,MUTED,false);\n        hint.setGravity(Gravity.CENTER);\n        hint.setPadding(0,dp(5),0,dp(12));\n        calendar.addView(hint);\n\n        String[] weekdays=TimeUtil.weekdayNames(this);\n        LinearLayout weekHeader=new LinearLayout(this);\n        weekHeader.setOrientation(LinearLayout.HORIZONTAL);\n        for(int i=0;i<7;i++){\n            TextView w=text(weekdays[i],13,MUTED,true);\n            w.setGravity(Gravity.CENTER);\n            weekHeader.addView(w,new LinearLayout.LayoutParams(0,dp(30),1));\n        }\n        calendar.addView(weekHeader);\n\n        LocalDate first=historyMonth.atDay(1);\n        int leading=first.getDayOfWeek().getValue()-1; // Monday = 0\n        int days=historyMonth.lengthOfMonth();\n        int cell=0;\n        for(int week=0;week<6;week++){\n            LinearLayout weekRow=new LinearLayout(this);\n            weekRow.setOrientation(LinearLayout.HORIZONTAL);\n            boolean hasDay=false;\n            for(int col=0;col<7;col++,cell++){\n                int day=cell-leading+1;\n                if(day<1 || day>days){\n                    LinearLayout blank=new LinearLayout(this);\n                    weekRow.addView(blank,new LinearLayout.LayoutParams(0,dp(70),1));\n                    continue;\n                }\n                hasDay=true;\n                LocalDate date=historyMonth.atDay(day);\n                weekRow.addView(historyDayCell(meds,date),new LinearLayout.LayoutParams(0,dp(70),1));\n            }\n            if(hasDay) calendar.addView(weekRow);\n        }\n\n        LinearLayout legend=new LinearLayout(this);\n        legend.setOrientation(LinearLayout.HORIZONTAL);\n        legend.setGravity(Gravity.CENTER);\n        legend.setPadding(0,dp(10),0,0);\n        TextView lo=text("O  "+I18n.t(this,"calendar_all_done"),12,BLUE,true);lo.setGravity(Gravity.CENTER);\n        TextView lp=text("△  "+I18n.t(this,"calendar_partial"),12,WARNING,true);lp.setGravity(Gravity.CENTER);\n        TextView lx=text("X  "+I18n.t(this,"calendar_none_done"),12,Color.rgb(190,70,70),true);lx.setGravity(Gravity.CENTER);\n        legend.addView(lo,new LinearLayout.LayoutParams(0,ViewGroup.LayoutParams.WRAP_CONTENT,1));\n        legend.addView(lp,new LinearLayout.LayoutParams(0,ViewGroup.LayoutParams.WRAP_CONTENT,1));\n        legend.addView(lx,new LinearLayout.LayoutParams(0,ViewGroup.LayoutParams.WRAP_CONTENT,1));\n        calendar.addView(legend);\n\n        Button todayButton=smallButton(I18n.t(this,"today"));\n        todayButton.setOnClickListener(v->{historyMonth=java.time.YearMonth.now();historySelectedDate=LocalDate.now();showHistory();});\n        calendar.addView(todayButton,matchWrap(dp(12),0));\n        content.addView(calendar,matchWrap(0,dp(12)));\n\n        addHistoryDayDetails(meds,historySelectedDate);\n    }\n\n    private View historyDayCell(List<Medicine> meds, LocalDate date){\n        LinearLayout cell=new LinearLayout(this);\n        cell.setOrientation(LinearLayout.VERTICAL);\n        cell.setGravity(Gravity.CENTER);\n        cell.setPadding(dp(2),dp(4),dp(2),dp(4));\n        boolean selected=date.equals(historySelectedDate);\n        boolean today=date.equals(LocalDate.now());\n        if(selected) cell.setBackground(round(SOFT_BLUE,15,BLUE,1));\n        else if(today) cell.setBackground(round(Color.WHITE,15,Color.rgb(180,205,230),1));\n\n        TextView day=text(String.valueOf(date.getDayOfMonth()),15,selected?BLUE_DARK:TEXT,selected||today);\n        day.setGravity(Gravity.CENTER);\n        cell.addView(day);\n\n        String status=historyDateStatus(meds,date);\n        int statusColor="O".equals(status)?BLUE:("△".equals(status)?WARNING:Color.rgb(190,70,70));\n        TextView mark=text(status.isEmpty()?" ":status,18,status.isEmpty()?MUTED:statusColor,true);\n        mark.setGravity(Gravity.CENTER);\n        cell.addView(mark);\n        cell.setOnClickListener(v->{historySelectedDate=date;showHistory();});\n        return cell;\n    }\n\n    private String historyDateStatus(List<Medicine> meds, LocalDate date){\n        LocalDate today=LocalDate.now();\n        if(date.isAfter(today)) return "";\n        int scheduled=0;\n        int taken=0;\n        boolean allTimesPassed=true;\n        LocalTime now=LocalTime.now();\n        for(Medicine m:meds){\n            if(!MedicationStore.isDayEnabled(m,date)) continue;\n            for(String slot:m.times){\n                scheduled++;\n                if(MedicationStore.isTaken(this,m.id,date,slot)) taken++;\n                if(date.equals(today) && now.isBefore(LocalTime.parse(slot))) allTimesPassed=false;\n            }\n        }\n        if(scheduled==0) return "";\n        if(taken==scheduled) return "O";\n        if(taken>0) return "△";\n        if(date.isBefore(today) || allTimesPassed) return "X";\n        return "";\n    }\n\n    private void addHistoryDayDetails(List<Medicine> meds, LocalDate date){\n        TextView selectedTitle=text(TimeUtil.date(this,date),22,TEXT,true);\n        selectedTitle.setPadding(dp(4),dp(4),0,dp(8));\n        content.addView(selectedTitle);\n\n        boolean any=false;\n        LocalDate today=LocalDate.now();\n        LocalTime now=LocalTime.now();\n        for(Medicine m:meds){\n            if(!MedicationStore.isDayEnabled(m,date)) continue;\n            for(String slot:m.times){\n                any=true;\n                boolean taken=MedicationStore.isTaken(this,m.id,date,slot);\n                boolean pending=date.isAfter(today) || (date.equals(today) && now.isBefore(LocalTime.parse(slot)));\n                LinearLayout row=card();\n                row.setOrientation(LinearLayout.HORIZONTAL);\n                row.setGravity(Gravity.CENTER_VERTICAL);\n\n                String icon=taken?"O":(pending?"–":"X");\n                int iconColor=taken?Color.WHITE:(pending?MUTED:Color.WHITE);\n                int iconBg=taken?BLUE:(pending?Color.rgb(242,244,247):Color.rgb(210,85,85));\n                TextView iv=text(icon,21,iconColor,true);\n                iv.setGravity(Gravity.CENTER);\n                iv.setBackground(round(iconBg,26,0,0));\n                row.addView(iv,new LinearLayout.LayoutParams(dp(52),dp(52)));\n\n                LinearLayout tx=new LinearLayout(this);\n                tx.setOrientation(LinearLayout.VERTICAL);\n                tx.setPadding(dp(12),0,0,0);\n                tx.addView(text(m.name+" · "+TimeUtil.time(this,slot),18,TEXT,true));\n                String detail=taken\n                        ? I18n.t(this,"dose_taken_prefix",TimeUtil.time(this,MedicationStore.takenTime(this,m.id,date,slot)))\n                        : (pending?I18n.t(this,"scheduled"):I18n.t(this,"missed"));\n                tx.addView(text(detail,15,taken?BLUE:(pending?MUTED:WARNING),taken));\n                row.addView(tx,new LinearLayout.LayoutParams(0,ViewGroup.LayoutParams.WRAP_CONTENT,1));\n                if(taken) row.setOnClickListener(v->confirmUndo(m.id,date,slot));\n                content.addView(row,matchWrap(0,dp(7)));\n            }\n        }\n        if(!any){\n            TextView none=text(I18n.t(this,"no_scheduled"),15,MUTED,false);\n            none.setPadding(dp(8),dp(4),0,dp(12));\n            content.addView(none);\n        }\n    }\n\n    private void moveHistoryMonth(int delta){\n        historyMonth=historyMonth.plusMonths(delta);\n        int day=Math.min(historySelectedDate.getDayOfMonth(),historyMonth.lengthOfMonth());\n        historySelectedDate=historyMonth.atDay(day);\n        showHistory();\n    }'''

if old not in s:
    raise SystemExit('existing history block missing')
s = s.replace(old, new, 1)
MAIN.write_text(s, encoding='utf-8')

